package ro.leo.visual;
import java.io.*;import java.nio.file.*;import java.util.*;
public final class FileTransfersTest {
    static void check(boolean v,String why){if(!v)throw new AssertionError(why);}
    public static void main(String[] args)throws Exception{File a=Files.createTempDirectory("leo-copy-source").toFile(),b=Files.createTempDirectory("leo-copy-dest").toFile();try{File source=new File(a,"Știre.bin");byte[] expected=new byte[190000];new Random(42).nextBytes(expected);Files.write(source.toPath(),expected);File copy=FileTransfers.transfer(a,source,b,b,false);check(source.isFile()&&Arrays.equals(expected,Files.readAllBytes(copy.toPath())),"verified binary copy");try{FileTransfers.transfer(a,source,b,b,false);throw new AssertionError("overwrote existing");}catch(IOException good){}File movedFolder=new File(b,"moved");movedFolder.mkdir();File moved=FileTransfers.transfer(a,source,b,movedFolder,true);check(!source.exists()&&FileTransfers.digest(copy).equals(FileTransfers.digest(moved)),"cross-directory move verified");File escape=new File(a,"../outside.bin");try{FileTransfers.transfer(a,escape,b,b,false);throw new AssertionError("escaped boundary");}catch(IOException good){}check(FileTransfers.search(b,"stire").size()==2,"accent-insensitive recursive search");File link=new File(b,"link.bin");Files.createSymbolicLink(link.toPath(),copy.toPath());check(FileTransfers.search(b,"link").isEmpty(),"search ignores symlinks");System.out.println("PASS verified copy/move, conflicts preserved, boundary checks, accent search and symlink exclusion");}finally{for(File root:new File[]{a,b})try(java.util.stream.Stream<Path> paths=Files.walk(root.toPath())){paths.sorted(Comparator.reverseOrder()).forEach(path->{try{Files.delete(path);}catch(IOException e){throw new RuntimeException(e);}});}}}
}
